package remframework.geometry.discovery;

import java.nio.file.*;
import java.util.*;
import remframework.geometry.discovery.configuration.*;
import remframework.geometry.discovery.experiment.*;
import remframework.geometry.discovery.realization.session.*;

/** Deterministic simultaneous/continuation comparison artifact for the normalized N=20 request. */
public final class ContinuationComparisonMain {
    private ContinuationComparisonMain(){}
    public static void main(String[] args)throws Exception{int limit=args.length>1?Integer.parseInt(args[1]):2_000;Path output=Path.of(args.length>0?args[0]:"target/n20-continuation-comparison.csv");ConfigurationRequest generation=ConfigurationRequest.byFaceCount(12,3,GeometryEmbeddingDimension.THREE_D,ExperimentProfile.CONVEX_POLYHEDRAL_VOLUME).withFaceComposition(FaceComposition.uniform(5));Configuration c=new ConfigurationGenerator().generate(generation).configurations().getFirst();List<String> lines=new ArrayList<>(List.of("strategy,seed,total_iteration,stage,stage_state,worst_constraint,worst_ratio,edge_error,planarity_error,angle_error,max_velocity,stagnation,orientation,convexity_max,convexity_rms,convexity_violations,status"));for(RealizationStrategy strategy:RealizationStrategy.values())for(long seed=42;seed<=46;seed++){TestRequest request=request(c,generation,seed,limit,strategy);IncrementalSession session=new IncrementalSession(c,request);session.run();ContinuationSnapshot s=session.continuationSnapshot();OrientationConvexityDiagnostics o=session.orientationConvexityDiagnostics();ThreeDConstraintDiagnostics d=session.threeDConstraintDiagnostics();String status=session.result()==null?session.scientificState().name():session.result().status().code().name();lines.add(String.join(",",strategy.name(),Long.toString(seed),Integer.toString(session.iteration()),s.stageId(),s.state().name(),s.worstConstraint(),Double.toString(s.worstRatio()),Double.toString(session.maximumEdgeError()),Double.toString(d.maximumFacePlanarityError()),Double.toString(d.maximumFaceAngleDeviation()),Double.toString(session.metrics().maximumNodeSpeed()),session.stagnationStatus().classification().name(),o.orientation().name(),Double.toString(o.maximumConvexityViolation()),Double.toString(o.rmsConvexityViolation()),Integer.toString(o.violatingPairs()),status));}Files.createDirectories(output.toAbsolutePath().getParent());Files.write(output,lines);System.out.println(output.toAbsolutePath());}
    private static TestRequest request(Configuration c,ConfigurationRequest generation,long seed,int limit,RealizationStrategy strategy){ThreeDExperimentConditions conditions=new ThreeDExperimentConditions(FacePlanarityMode.REQUIRE_PLANAR_FACES,FaceAngleConditionMode.REQUIRE_EQUAL_ANGLES_WITHIN_EACH_FACE,DihedralConditionMode.MEASURE_ONLY,RegularityMode.MEASURE_ONLY,RegularityMode.MEASURE_ONLY,RegularityMode.MEASURE_ONLY,FacePlaneRadiusMode.REQUIRE_EQUAL_FACE_PLANE_RADII,RegularityMode.MEASURE_ONLY,GeometryCenterDefinition.VERTEX_CENTROID,1e-4,1e-3,1e-3);TestRequest request=new TestRequest(c.id(),GeometryEmbeddingDimension.THREE_D,1,seed,1,null,GeometrySymmetryPolicy.MEASURE_ONLY,Math.max(limit,10_000),ExperimentProfile.CONVEX_POLYHEDRAL_VOLUME,null,null,null,1e-3,1e-7,1e-9,1e-6,null,0,0,conditions,BenchmarkPreset.NONE,ThreeDConstraintStrengths.defaults()).withFaceComposition(FaceComposition.uniform(5)).withParameterDerivation(generation);return request.withContinuation(strategy==RealizationStrategy.SEQUENTIAL_CONTINUATION?ContinuationSettings.sequential(conditions,20,limit,100):ContinuationSettings.simultaneous());}
}
